$ErrorActionPreference='Stop'; if (@(Get-ExecutionPolicy -List | Where-Object {$_.ExecutionPolicy -in @('AllSigned','Restricted')}).Count) {throw 'IT signing policy restricts this installer'}; [Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; $jjDir=Join-Path $env:TEMP ('jjaitech-install-'+[guid]::NewGuid().ToString('N')); New-Item -ItemType Directory -Path $jjDir | Out-Null; $jjZip=Join-Path $jjDir 'release.zip'; Invoke-WebRequest -UseBasicParsing -Uri 'https://github.com/JachinLan/jjaitech-memory/releases/download/v1.3.0-rc.3-online.1/jjaitech-memory-windows-1.3.0-rc.3-online.1.zip' -OutFile $jjZip -TimeoutSec 120; if ((Get-FileHash -Algorithm SHA256 -LiteralPath $jjZip).Hash.ToLowerInvariant() -ne 'aa8600b61d7fc59b6f1ffefee9d77f1112af78229fa70cb25b505161ff50627d') {throw 'Download checksum mismatch; installation stopped'}; Expand-Archive -LiteralPath $jjZip -DestinationPath $jjDir; & ([scriptblock]::Create([IO.File]::ReadAllText((Join-Path $jjDir 'jjaitech-memory/distribution/bootstrap-windows.ps1')))) -PackageRoot $jjDir
